/* Dev-time export: the kernel rule table -> the site data file.
 *
 * `net-sim/l3sm-l3nm/app/rules.js` is the only place rule data is edited. This
 * script loads it the same way the browser does (through load-classic.mjs),
 * serialises every group it exposes, and writes _data/ietf-3tier-rules.json so
 * that a Jekyll page can render the rules at build time and the site's search
 * index can see them. The direction is one way: the kernel never reads the
 * generated file, so net-sim/ stays independent of the site template.
 *
 * Run: node tools/build-rules-data.mjs          write the export
 *      node tools/build-rules-data.mjs --check  fail if the export is stale
 *      RULES_EXPORT_PATH=<file>                 act on another file, so the
 *                                               drift check itself can be run
 *                                               without touching the export
 *
 * The output is byte-stable for a given rules.js: fixed group order, no
 * timestamp, no absolute path.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, isAbsolute, join } from 'node:path';
import process from 'node:process';
import { loadApp, repoRoot } from './load-classic.mjs';

const SOURCE = 'net-sim/l3sm-l3nm/app/rules.js';
/* The default target is the committed export; an override exists only so that
   the drift check can be demonstrated against a scratch copy. */
const override = process.env.RULES_EXPORT_PATH;
const COMMITTED = join(repoRoot, '_data', 'ietf-3tier-rules.json');
const OUTPUT = override ? (isAbsolute(override) ? override : join(repoRoot, override)) : COMMITTED;
const OUTPUT_LABEL = override || '_data/ietf-3tier-rules.json';

/* Every group `ns.rules` exposes, in the order it is written out. */
const GROUPS = [
  'RFC', 'SECTIONS', 'CATEGORIES', 'CONFIDENCE', 'FIELDS', 'RULES',
  'SCOPE', 'PROVIDER', 'PRESET_INPUT', 'DIFFERENCES', 'PLACEHOLDER_DRAFT'
];

const GENERATED = 'Generated by tools/build-rules-data.mjs from ' + SOURCE +
  '. Do not edit this file: edit that source and run' +
  ' "node tools/build-rules-data.mjs", or check it has been re-exported with' +
  ' "node tools/build-rules-data.mjs --check".';

function build() {
  const { rules } = loadApp(['rules.js']);
  const missing = GROUPS.filter((group) => !(group in rules));
  if (missing.length) {
    fail(`the kernel exposes no ${missing.join(', ')} group; update GROUPS in this script`);
  }
  const payload = { _generated: GENERATED };
  for (const group of GROUPS) { payload[group] = rules[group]; }
  return JSON.stringify(payload, null, 2) + '\n';
}

function fail(message) {
  console.error(`build-rules-data: ${message}`);
  process.exit(1);
}

/* Where an on-disk export disagrees with a fresh one. Reported by group, and
 * for the rule table by rule id, so a hand edit is easy to point at. */
function reportDrift(onDisk, fresh) {
  const problems = [];
  for (const group of ['_generated'].concat(GROUPS)) {
    const before = onDisk[group];
    const after = fresh[group];
    if (JSON.stringify(before) === JSON.stringify(after)) { continue; }
    if (group !== 'RULES') { problems.push(`${group} differs`); continue; }
    problems.push(`RULES differs (${describeRules(before, after)})`);
  }
  return problems;
}

function describeRules(onDisk, fresh) {
  const list = Array.isArray(onDisk) ? onDisk : [];
  const want = Array.isArray(fresh) ? fresh : [];
  const byId = new Map(list.map((rule) => [rule && rule.id, rule]));
  const changed = [];
  const removed = [];
  for (const rule of want) {
    const previous = byId.get(rule.id);
    if (previous === undefined) { changed.push(`${rule.id} added`); continue; }
    byId.delete(rule.id);
    if (JSON.stringify(previous) !== JSON.stringify(rule)) { changed.push(rule.id); }
  }
  for (const id of byId.keys()) { removed.push(`${id} only in the export`); }
  return changed.concat(removed).join(', ') || 'shape changed';
}

const check = process.argv.includes('--check');
const fresh = build();

if (!check) {
  mkdirSync(dirname(OUTPUT), { recursive: true });
  writeFileSync(OUTPUT, fresh, 'utf8');
  const payload = JSON.parse(fresh);
  console.log(`build-rules-data: wrote ${OUTPUT_LABEL} ` +
    `(${payload.RULES.length} rules, ${payload.FIELDS.length} fields, ${Buffer.byteLength(fresh)} bytes)`);
  process.exitCode = 0;
} else if (!existsSync(OUTPUT)) {
  fail(`${OUTPUT_LABEL} is missing; run "node tools/build-rules-data.mjs"`);
} else {
  const onDiskText = readFileSync(OUTPUT, 'utf8');
  if (onDiskText === fresh) {
    console.log(`build-rules-data: ${OUTPUT_LABEL} matches ${SOURCE}`);
    process.exitCode = 0;
  } else {
    let onDisk = null;
    try { onDisk = JSON.parse(onDiskText); } catch (error) {
      fail(`${OUTPUT_LABEL} is not valid JSON (${error.message})`);
    }
    fail(`${OUTPUT_LABEL} is stale: ` + reportDrift(onDisk, JSON.parse(fresh)).join('; '));
  }
}
